'use strict';
const PlanAccess={
 tabUrl(tab){const q=new URLSearchParams(location.search);q.set('tab',tab);q.delete('status');return '/loading-plans?'+q;},
 groupActions(g){if(!LoadingPlans.can()||g.cancelled_at)return `<a class="button secondary" href="/loading-plans/${g.id}">查看</a>`;return `<a class="button secondary" href="/loading-plans/${g.id}">查看</a><a class="button secondary" href="/loading-plans/${g.id}/edit">编辑</a><a class="button secondary" href="/loading-plans/${g.id}/cancel">取消</a><a class="button primary" href="/loading-plans/${g.id}/orders/new">新建车辆计划单</a>`;},
 groupTable(groups){return `<div class="business-table"><table><thead><tr><th>装车计划 / 名称</th><th>发票号 / 装箱单号</th><th>客户 / 合同</th><th>车辆计划单数</th><th>状态</th><th>操作</th></tr></thead><tbody>${groups.map(g=>`<tr data-plan-group="${g.id}"><td><a data-no-i18n href="/loading-plans/${g.id}">${esc(g.code)}</a><br><span data-no-i18n>${esc(g.name)}</span></td><td data-no-i18n>${esc(g.invoice_no||'—')}<br>${esc(g.packing_list_no||'—')}</td><td data-no-i18n>${esc(g.customer_name)}<br>${esc(g.contract_no||'—')}</td><td>${Number(g.document_count||0)}</td><td>${g.cancelled_at?'已取消':'进行中'}</td><td><div class="plan-row-actions">${this.groupActions(g)}</div></td></tr>`).join('')||'<tr><td colspan="6">暂无装车计划</td></tr>'}</tbody></table></div>`;},
 async list(){const q=new URLSearchParams(location.search),tab=q.get('tab')==='documents'?'documents':'plans',[groups,docs]=await Promise.all([API.request('/loading-plans?'+q),API.request('/loading-plan-documents?'+q)]);Router.page('装车计划',`<div class="business-toolbar">${LoadingPlans.can()?'<a class="button primary" href="/loading-plans/new">新建装车计划</a>':''}<a class="button secondary" href="/sales-plans">查看销售计划</a></div><nav class="plan-view-tabs" aria-label="计划记录分类"><a class="button ${tab==='plans'?'primary':'secondary'}" href="${esc(this.tabUrl('plans'))}" aria-current="${tab==='plans'?'page':'false'}">装车计划</a><a class="button ${tab==='documents'?'primary':'secondary'}" href="${esc(this.tabUrl('documents'))}" aria-current="${tab==='documents'?'page':'false'}">装车计划单（车辆）</a></nav><p class="plan-workflow-help">装车计划维护发票和运输资料；每辆车需在计划下新建一张装车计划单，再与出库管理的装车单匹配。</p><form id="lp-search" class="shipping-filters"><input type="hidden" name="tab" value="${tab}"><label>${tab==='plans'?'计划号 / 名称 / 发票号 / 客户':'计划单号 / 装箱单号 / 客户 / 车牌'}<input name="search" value="${esc(q.get('search')||'')}" maxlength="160"></label>${tab==='documents'?`<label>装车计划单状态<select name="status"><option value="">全部状态</option>${Object.entries(LoadingPlans.states).map(([k,v])=>`<option value="${k}" ${q.get('status')===k?'selected':''}>${v}</option>`).join('')}</select></label>`:''}<button class="button secondary">查询</button></form>${tab==='plans'?this.groupTable(groups.items):LoadingPlans.table(docs.items)}<p>最近500条</p>`);$('lp-search').onsubmit=e=>{e.preventDefault();Router.go('/loading-plans?'+new URLSearchParams(new FormData(e.target)));};},
 async group(id){const {group:g,documents}=await API.request('/loading-plans/'+id);Router.page('装车计划 · '+g.name,LoadingPlans.context(g)+`<div class="business-toolbar">${this.groupActions(g)}<a class="button secondary" href="/loading-plans">装车计划列表</a></div><p data-no-i18n>${esc(g.code)} · ${esc(g.note||'')}</p><section class="lp-load-summary"><h3>公共运输资料</h3><dl class="lp-fields">${Object.entries(LoadingPlans.headerLabels||{}).map(([key,label])=>'<dt>'+label+'</dt><dd data-no-i18n>'+esc(g[key]||'待补充')+'</dd>').join('')}</dl></section><h3>本计划的车辆计划单</h3>${documents.length?LoadingPlans.table(documents):`<div class="plan-empty-state"><p>尚未创建车辆装车计划单，出库管理暂时无法匹配此计划。</p>${LoadingPlans.can()&&!g.cancelled_at?'<p>点击上方“新建车辆计划单”继续。</p>':'<p>请联系出口主管或物流经理创建车辆计划单。</p>'}</div>`}${g.cancelled_at?'<p>计划已取消：'+esc(g.cancel_reason)+'</p>':''}`);},
 async cancel(id){if(!LoadingPlans.can())throw Error('没有维护装车计划的权限');const {group:g,documents}=await API.request('/loading-plans/'+id),linked=documents.filter(d=>d.loading_id);Router.page('取消装车计划',LoadingPlans.context(g)+`<p data-no-i18n>${esc(g.code)} · ${esc(g.name)}</p>${g.cancelled_at?'<p>装车计划已取消。</p>':linked.length?`<p class="dialog-notice">${linked.some(d=>d.status==='OUTBOUND')?'已有车辆正式出库，本计划不能取消。':'本计划含已匹配的车辆计划单，请先解除对应装车单的匹配，再取消计划。'}</p>${LoadingPlans.table(linked)}`:`<p>取消后，本计划及所有尚未匹配的车辆计划单将保留历史并标记为已取消。</p><form id="lp-cancel-form" class="user-form"><label>取消原因<input name="reason" required maxlength="1000"></label><button class="button primary" type="submit">确认取消</button><p class="error" id="lp-cancel-error" role="alert"></p></form>`}<p><a class="button secondary" href="/loading-plans/${id}">返回装车计划</a></p>`);LoadingPlans.bindCancel('/loading-plans/'+id,g.version,()=>Router.go('/loading-plans'));},
 async matchingHelp(id){const form=$('lp-load-form'),select=$('lp-match-select');if(!form||!select)return;const q=new URLSearchParams(location.search),bar=document.createElement('div');bar.className='plan-matching-search';bar.innerHTML=`<label>查找车辆计划单<input id="lp-document-search" maxlength="160" value="${esc(q.get('plan_search')||'')}" placeholder="计划单号 / 装箱单号 / 客户 / 车牌"></label><button class="button secondary" type="button" id="lp-document-find">查询计划单</button><button class="button secondary" type="button" id="lp-document-refresh">刷新可用计划单</button>`;select.closest('label').before(bar);const find=()=>{const next=new URLSearchParams(location.search);next.set('plan_search',$('lp-document-search').value.trim());next.delete('document_id');Router.go(location.pathname+'?'+next);};$('lp-document-find').onclick=find;$('lp-document-search').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();find();}};$('lp-document-refresh').onclick=()=>Router.show();const helper=document.createElement('section');helper.className='plan-match-help';helper.id='lp-match-help';if(select.options.length>1){helper.innerHTML=`<p>请选择一张待匹配的车辆装车计划单，列表同时显示计划单号、装箱单号、客户、合同和车牌。</p>`;}else if(q.get('plan_search')){helper.innerHTML='<p>未找到符合查询条件的待匹配车辆计划单，请清空查询或检查计划单状态。</p>';}else{const {items:groups}=await API.request('/loading-plans');helper.innerHTML='<p>暂无可匹配的车辆装车计划单。上级装车计划不能直接作为车辆计划单匹配。</p>'+(LoadingPlans.can()?groups.filter(g=>!g.cancelled_at).map(g=>`<p><span data-no-i18n>${esc(g.code)} · ${esc(g.name)}</span> <a class="button secondary" href="/loading-plans/${g.id}/orders/new">新建车辆计划单</a></p>`).join(''):'<p>请联系出口主管或物流经理，在装车计划下创建车辆计划单后，点击刷新可用计划单。</p>')+'<a class="button secondary" href="/loading-plans?tab=documents">查看车辆计划单及匹配状态</a>';}
 select.closest('label').after(helper);if(!id&&q.get('document_id')&&!select.value){try{const {document:d}=await API.request('/loading-plan-documents/'+encodeURIComponent(q.get('document_id')));if(d.status!=='WAITING')helper.innerHTML=`<p>此车辆计划单当前状态：${LoadingPlans.badge(d.status)}，不能重复匹配。</p><a class="button secondary" href="/loading-plans/orders/${d.id}">查看车辆计划单</a>`;}catch(err){helper.textContent=err.message;}}
 }
};
LoadingPlans.list=PlanAccess.list.bind(PlanAccess);LoadingPlans.group=PlanAccess.group.bind(PlanAccess);
const accessTable=LoadingPlans.table.bind(LoadingPlans);LoadingPlans.table=function(items){const box=document.createElement('div');box.innerHTML=accessTable(items);for(let n=0;n<items.length;n++){const d=items[n],row=box.querySelectorAll('tbody tr')[n];if(!row)continue;row.dataset.planDocument=d.id;const actions=row.lastElementChild;if(LoadingPlans.can()&&!['OUTBOUND','CANCELLED'].includes(d.status)){const a=document.createElement('a');a.className='button secondary';a.href='/loading-plans/orders/'+d.id+'/edit';a.textContent='编辑';actions.append(' ',a);}if(d.status==='WAITING'&&Business.can('loading-plan:match')&&Business.can('load:write')){const a=document.createElement('a');a.className='button primary';a.href='/outbounds/loads/new?document_id='+d.id;a.textContent='新建并匹配装车单';actions.append(' ',a);}}return box.innerHTML;};
const accessLoadForm=LoadingPlans.loadForm.bind(LoadingPlans);LoadingPlans.loadForm=async function(id){await accessLoadForm(id);await PlanAccess.matchingHelp(id);};
const accessPermission=Router.permission.bind(Router);Router.permission=path=>/^\/loading-plans\/[0-9a-f-]{36}\/cancel$/.test(path)?'loading-plan:write':accessPermission(path);
const accessInit=Router.init.bind(Router);Router.init=async function(){this.add(/^\/loading-plans\/([0-9a-f-]{36})\/cancel$/,id=>PlanAccess.cancel(id));return accessInit();};

const accessFlowForm=Flow.loadForm.bind(Flow);Flow.loadForm=async function(){await accessFlowForm();if($('v26-load')&&!Business.can('loading-plan:match')){const note=document.createElement('p');note.className='dialog-notice';note.textContent='当前账户可创建未关联计划的装车单。如需匹配车辆计划单，请使用已获匹配权限的账户。';$('v26-load').before(note);}};
